CustomField.formula:
/*Re_Processor_Name__c+ Text (Re_Process_DateTime__c)*/
if(Re_Process_DateTime__c != NULL, Re_Processor_Name__c +' '+ TEXT(Day(DATEVALUE(Re_Process_DateTime__c ) ) ) &"/"&TEXT(MONTH(DATEVALUE(Re_Process_DateTime__c ) ) ) &"/"& TEXT(YEAR(DATEVALUE(Re_Process_DateTime__c ) ) ) &" "&(IF( OR( VALUE( MID( TEXT( Re_Process_DateTime__c+ (5.5/24)), 12, 2 ) ) = 0, VALUE( MID( TEXT( Re_Process_DateTime__c+ (5.5/24) ), 12, 2 ) ) = 12 ), "12", TEXT( VALUE( MID( TEXT( Re_Process_DateTime__c+ (5.5/24) ), 12, 2 ) ) - IF( VALUE( MID( TEXT( Re_Process_DateTime__c+ (5.5/24)), 12, 2 ) ) < 12, 0, 12 ) ) ) & ":" & MID( TEXT( Re_Process_DateTime__c+ (5.5/24) ), 15, 2 ) & " " & IF( VALUE( MID( TEXT( Re_Process_DateTime__c+ (5.5 /24)), 12, 2 ) ) < 12, "AM", "PM" ))
,' ')
